/**
 * A LIVE'S KEY AT REST (migration 110, docs/wiki/services/lives.md#the-live-key-at-rest).
 *
 * The live key is generated by the broadcaster's client and served to every member who may watch
 * (L2, Q4); it opens the live's segments and its chat (`live_chat_messages.sealed`). Stored in the
 * clear, a database copy or a backup alone opened both. So the row keeps it SEALED, under a key
 * derived from LIVE_KEY_ENCRYPTION_SECRET (`common/secret-box.ts`: AES-256-GCM, a fresh IV per seal,
 * HKDF per purpose), with the live id and the key version as additional authenticated data - a
 * ciphertext copied to another live's row, or relabelled with another version, does not open.
 *
 * THIS FILE IS THE ONLY READER of the stored key: `openLiveKey` (and its HTTP form
 * `openLiveKeyOr503`) for the viewer's `get` and for the report check of a chat line
 * (`ModerationService`), `sealLiveKey` for the start and the backfill. Every failure to open is a
 * {@link LiveKeyUnavailableError} logged at ERROR here, never a null.
 *
 * `liveKeyVersion` names the secret a row was sealed under. Only {@link LIVE_KEY_VERSION} opens
 * today; a rotation adds the next version's secret beside this one, seals new lives under it, and
 * keeps the old one until the last row of the old version is purged (a live lives an hour at most).
 *
 * THE PREVIOUS FORMAT (durable-rules: an at-rest envelope change ships its reader for the previous
 * format in the same commit): a row written before migration 110, or by the previous release's
 * replica during the rolling deploy, holds the plaintext in `"liveKey"`. It is read as such, at
 * WARN naming the live, and the live sweep seals it (`LivesService.sealPlaintextKeys`). Removal:
 * docs/wiki/legacy-compatibility.md.
 *
 * NEVER LOGS the key or its ciphertext.
 */
import { Logger, ServiceUnavailableException } from '@nestjs/common';
import {
  isSecretBoxConfigured,
  openSecret,
  sealSecret,
  SecretBoxOpenError,
  SecretBoxUnavailableError,
} from '../common/secret-box';
import { LIVE_KEY_HEX_RE } from './live.constants';

/** The environment variable holding the secret live keys are sealed under (32+ characters). */
export const LIVE_KEY_ENCRYPTION_SECRET_ENV = 'LIVE_KEY_ENCRYPTION_SECRET';
/** The key version every new seal is written with, and the only one that opens. */
export const LIVE_KEY_VERSION = 1;

/** The HKDF purpose of the live key's sealing key, distinct from every other secret-box use. */
export const LIVE_KEY_PURPOSE = 'live-key';
const logger = new Logger('LiveKeyAtRest');

/** Why a live's stored key could not be read - a CODE, never prose a caller would parse. */
export type LiveKeyUnavailableReason =
  | 'secret-missing'
  | 'unknown-version'
  | 'does-not-open'
  | 'malformed'
  | 'absent';

/** The stored key could not be read: typed by its reason, logged at ERROR where it is thrown. */
export class LiveKeyUnavailableError extends Error {
  constructor(
    readonly liveId: string,
    readonly reason: LiveKeyUnavailableReason
  ) {
    super(`live key of ${liveId} unavailable: ${reason}`);
    this.name = 'LiveKeyUnavailableError';
  }
}

/** The columns a reader selects: the sealed form, its version, and the previous plaintext form. */
export interface StoredLiveKey {
  liveKeyCiphertext: string | null;
  liveKeyVersion: number | null;
  liveKey: string | null;
}

/** The SQL select list of {@link StoredLiveKey}, prefixed with a table alias when given. */
export function storedLiveKeyColumns(alias?: string): string {
  const p = alias ? `${alias}.` : '';
  return `${p}"liveKeyCiphertext", ${p}"liveKeyVersion", ${p}"liveKey"`;
}

/** The additional authenticated data: the live and the version, so neither can be swapped. */
export function liveKeyContext(liveId: string, version: number): string {
  return `live:${liveId.toLowerCase()}:v${version}`;
}

/** True when lives can be started: a key can be sealed. */
export function isLiveKeySealingConfigured(): boolean {
  return isSecretBoxConfigured(LIVE_KEY_ENCRYPTION_SECRET_ENV);
}

/**
 * Seals `keyHex` for `liveId` under the current version. Throws {@link LiveKeyUnavailableError}
 * (`secret-missing`) when no secret is configured, logged at ERROR.
 */
export function sealLiveKey(
  liveId: string,
  keyHex: string
): { liveKeyCiphertext: string; liveKeyVersion: number } {
  try {
    return {
      liveKeyCiphertext: sealSecret(
        LIVE_KEY_PURPOSE,
        liveKeyContext(liveId, LIVE_KEY_VERSION),
        keyHex,
        LIVE_KEY_ENCRYPTION_SECRET_ENV
      ),
      liveKeyVersion: LIVE_KEY_VERSION,
    };
  } catch (e) {
    if (e instanceof SecretBoxUnavailableError) throw unavailable(liveId, 'secret-missing');
    throw e;
  }
}

/** Logs and builds the typed error. */
function unavailable(liveId: string, reason: LiveKeyUnavailableReason): LiveKeyUnavailableError {
  logger.error(
    `[LIVE_KEY] the key of live ${liveId} cannot be read: ${reason}` +
      (reason === 'secret-missing'
        ? ` (${LIVE_KEY_ENCRYPTION_SECRET_ENV} is unset or shorter than 32 characters)`
        : '')
  );
  return new LiveKeyUnavailableError(liveId, reason);
}

/**
 * THE ONE OPEN of a live's stored key: the 64-hex key, or a {@link LiveKeyUnavailableError} logged
 * at ERROR. A row still in the previous format answers its plaintext, at WARN (see the file head).
 */
export function openLiveKey(liveId: string, stored: StoredLiveKey): string {
  if (stored.liveKeyCiphertext == null) {
    if (stored.liveKey != null && LIVE_KEY_HEX_RE.test(stored.liveKey)) {
      logger.warn(
        `[LIVE_KEY] live ${liveId} still holds its key in the previous, plaintext form - ` +
          `the live sweep seals it`
      );
      return stored.liveKey;
    }
    throw unavailable(liveId, stored.liveKey == null ? 'absent' : 'malformed');
  }
  if (stored.liveKeyVersion !== LIVE_KEY_VERSION) throw unavailable(liveId, 'unknown-version');
  let opened: string;
  try {
    opened = openSecret(
      LIVE_KEY_PURPOSE,
      liveKeyContext(liveId, stored.liveKeyVersion),
      stored.liveKeyCiphertext,
      LIVE_KEY_ENCRYPTION_SECRET_ENV
    );
  } catch (e) {
    if (e instanceof SecretBoxUnavailableError) throw unavailable(liveId, 'secret-missing');
    if (e instanceof SecretBoxOpenError) throw unavailable(liveId, 'does-not-open');
    throw e;
  }
  if (!LIVE_KEY_HEX_RE.test(opened)) throw unavailable(liveId, 'malformed');
  return opened;
}

/** {@link openLiveKey} for a route: an unreadable key answers 503 `LIVE_KEY_UNAVAILABLE`. */
export function openLiveKeyOr503(liveId: string, stored: StoredLiveKey): string {
  try {
    return openLiveKey(liveId, stored);
  } catch (e) {
    if (e instanceof LiveKeyUnavailableError) {
      throw new ServiceUnavailableException({ code: 'LIVE_KEY_UNAVAILABLE' });
    }
    throw e;
  }
}
